@Composable
fun AiImportConfirmDialog(
    onConfirm: () -> Unit,
    onDismiss: () -> Unit,
) {
    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(stringResource(R.string.ai_import_confirm_title)) },
        text = {
            Text(stringResource(R.string.ai_import_confirm_body))
        },
        confirmButton = {
            TextButton(onClick = onConfirm) { Text(stringResource(R.string.import_button)) }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text(stringResource(R.string.cancel)) }
        },
    )
}
